enactments:
# ══════════════════════════════════════════════════════════════════════════════
#  I2IDL-X enactments — I2IDL concepts → the Foxxi / Interego affordances that
#  enact them (pragmatic interpretants), plus role capabilities.
#  AI-DRAFTED. Publish with modal status Hypothetical. Each record carries its
#  rationale and confidence; the plain i2x:*By triple is materialized beside it.
#  Action IRIs dereference (302) to the manifest that defines target, method
#  and input shape — this graph links capabilities, it never redefines them.
# ══════════════════════════════════════════════════════════════════════════════

<{{ENACTMENTS}}> a owl:Ontology ;
    dct:title "I2IDL-X enactments"@en ;
    dct:description "Concept-to-capability links from the I2IDL glossary ({{I2IDL_RELEASE}}) to live Foxxi bridge and Interego relay affordances."@en ;
    dct:conformsTo <{{SHAPES}}> ;
    owl:imports <{{ONTOLOGY}}> ;
    prov:wasAttributedTo {{DRAFTER}} ;
    prov:generatedAtTime "{{NOW}}"^^xsd:dateTime ;
    prov:wasDerivedFrom <https://github.com/blakeplock/i2idl-linked-data/blob/{{COMMIT}}/public/glossary.jsonld> , <{{FOXXI_MANIFEST}}> , <https://relay.interego.xwisee.com/.well-known/operations> ;
    rdfs:comment "Modal status Hypothetical until ratified by i2x:RatificationVote. Role capabilities tagged [learning-engineer] are derived from the Foxxi manifest's own role tags."@en .

mappings:
# ══════════════════════════════════════════════════════════════════════════════
#  I2IDL-X mapping proposals — I2IDL concepts → external vocabularies (UNESCO
#  Thesaurus, Foxxi's xAPI, SCORM, cmi5, IEEE LER and ADL TLA ontologies, ADL's
#  xAPI and xAPI Profiles ontologies, schema.org, W3C VC, Interego). PROPOSALS,
#  not assertions: no skos:*Match triple appears here. A mapping triple exists
#  only after ratification (rules in i2idlx-rules). Every object IRI was checked
#  to exist in its vocabulary at build time; Foxxi's at release {{FOXXI_VERSION}}.
#  A proposal a later one replaces stays, with status superseded.
# ══════════════════════════════════════════════════════════════════════════════

<{{MAPPINGS}}> a owl:Ontology ;
    dct:title "I2IDL-X mapping proposals"@en ;
    dct:description "SKOS crosswalk proposals from the I2IDL glossary ({{I2IDL_RELEASE}}) to external vocabularies, held for editorial review."@en ;
    dct:conformsTo <{{SHAPES}}> ;
    owl:imports <{{ONTOLOGY}}> ;
    prov:wasAttributedTo {{DRAFTER}} ;
    prov:generatedAtTime "{{NOW}}"^^xsd:dateTime ;
    dct:references <{{UNESCO_SCHEME}}> ;
    dct:references {{FOXXI_IRIS}} ;
    rdfs:comment "Uses SKOS mapping predicates with the meanings in I2IDL's SEMANTIC-RELATIONSHIPS.md. standards-text proposals rest on the same normative text; evidence-cited proposals turn a citation I2IDL already makes (i2x:citedIn names the definition) into a mapping, with the predicate read from both texts; ai-drafted proposals need editorial review before ratification. A proposal that a later one replaces keeps its record and id, with status superseded and dct:isReplacedBy the new one. UNESCO Thesaurus terms are © UNESCO, CC BY-SA 3.0 IGO."@en .

releases:
# ══════════════════════════════════════════════════════════════════════════════
#  I2IDL release feed — derived from the public git history of
#  blakeplock/i2idl-linked-data (last commit per gs:publicationVersion).
#  Lets an agent answer "what changed since the release my decorations were
#  built against?" before trusting them. Facts about upstream; not editorial.
# ══════════════════════════════════════════════════════════════════════════════

<{{RELEASES}}> a owl:Ontology ;
    dct:title "I2IDL release feed (derived)"@en ;
    dct:description "One i2x:GlossaryRelease per published I2IDL version, chained by prov:wasRevisionOf, with concept additions, removals, definition revisions and relationship counts."@en ;
    dct:conformsTo <{{SHAPES}}> ;
    prov:wasDerivedFrom <https://github.com/blakeplock/i2idl-linked-data> ;
    prov:generatedAtTime "{{NOW}}"^^xsd:dateTime .

changes:
# ══════════════════════════════════════════════════════════════════════════════
#  I2IDL change history — derived from the public git history of
#  blakeplock/i2idl-linked-data, one PROV activity per release and one event
#  per kind of change, naming what each touched. It reconciles exactly: the
#  baseline release plus every addition minus every removal equals {{I2IDL_RELEASE}}
#  for concepts, relationship pairs, memberships, evidence, sources,
#  collections, I2IDL's own crosswalks and its proposed ontology
#  associations. Facts about upstream; not editorial judgement.
# ══════════════════════════════════════════════════════════════════════════════

<{{CHANGES}}> a owl:Ontology ;
    dct:title "I2IDL change history (derived)"@en ;
    dct:description "Machine-readable change history for the I2IDL Digital Learning Glossary: every release change since {{BASELINE}} as a prov:Activity that used the previous release and generated the next, with typed change events (concept added, relationship added, membership added, evidence classified or reclassified, source revised, ...)."@en ;
    dct:conformsTo <{{SHAPES}}> ;
    owl:imports <{{ONTOLOGY}}> ;
    i2x:baselineRelease <{{REL}}{{BASELINE}}> ;
    prov:wasDerivedFrom <https://github.com/blakeplock/i2idl-linked-data> , <{{RELEASES}}> ;
    prov:generatedAtTime "{{NOW}}"^^xsd:dateTime ;
    rdfs:seeAlso <https://github.com/blakeplock/i2idl-linked-data/blob/{{COMMIT}}/docs/ROADMAP.md#4-add-machine-readable-change-history> ;
    rdfs:comment {{CHANGE_COMMENT}}@en .
